function mapSVG(opts={}){
  const o=Object.entries(OBL).map(([id,v])=>`<path class="obl" data-id="${id}" d="${GEO.obl[id].d}"><title>${v.n}</title></path>`).join('');
  const labs=opts.labels===false?'':Object.entries(OBL).map(([id,v])=>`<text class="obl-label${id==='bokey'||id==='zakas'?' sm':''}" x="${GEO.obl[id].lab[0]}" y="${GEO.obl[id].lab[1]}">${v.n.replace(' облысы','').replace(' ордасы','')}</text>`).join('');
  const water=`<path class="water" d="${GEO.water[0]}"/><path class="water" d="${GEO.water[1]}"/><text class="water-label" x="${GEO.aralLab[0]}" y="${GEO.aralLab[1]}">Арал</text><text class="water-label" x="${GEO.balLab[0]}" y="${GEO.balLab[1]}">Балқаш</text><text class="water-label big" x="${GEO.caspian[0]}" y="${GEO.caspian[1]}">Каспий</text>`;
  const outline=`<path class="outline" d="${GEO.outline}"/>`;
  const rail=`<g data-layer="rail">${GEO.rails.map(d=>`<path class="rail" d="${d}"/>`).join('')}</g>`;
  const cities=`<g data-layer="city">${CITIES.map(c=>`<g class="city"><circle cx="${c[1]}" cy="${c[2]}" r="5"/><text x="${c[1]+(c[3]||8)}" y="${c[2]+(c[4]||-8)}" text-anchor="${c[5]||'start'}">${c[0]}</text></g>`).join('')}</g>`;
  const fairs=`<g data-layer="fair">${FAIRS.map(c=>`<g class="fair"><circle cx="${c[1]}" cy="${c[2]}" r="9"/><text x="${c[1]+(c[3]||12)}" y="${c[2]+(c[4]||20)}" text-anchor="${c[5]||'start'}">${c[0]}</text></g>`).join('')}</g>`;
  const evs=`<g data-layer="ev">${EVS.map(c=>`<g class="ev"><circle cx="${c[1]}" cy="${c[2]}" r="10"/><text x="${c[1]+(c[3]||0)}" y="${c[2]+(c[4]||32)}" text-anchor="${c[5]||'middle'}">${c[0]}</text></g>`).join('')}</g>`;
  return `<svg viewBox="0 0 1000 ${GEO.h}" role="img" aria-label="ХХ ғасыр басындағы қазақ облыстарының картасы">${o}${water}${outline}${labs}${opts.layers===false?'':rail+cities+fairs+evs}</svg>`;
}
