/* ============ STATE ============ */
const KEY='alash-site-v1';
let S={read:[],known:[],tasks:{}};
try{const v=JSON.parse(localStorage.getItem(KEY)||'null');if(v)S=Object.assign(S,v);}catch(e){}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){} updateTop();}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>el.hidden=true,1800);}
function overall(){
  const tp=Object.values(S.tasks).reduce((a,t)=>a+t.s,0), tm=TASKS.reduce((a,t)=>a+t.max,0);
  return {tp,tm,read:S.read.length,known:S.known.length,done:Object.keys(S.tasks).length};
}
function updateTop(){const o=overall();const pct=((o.read/10)*0.3+(o.known/30)*0.2+(o.done/5)*0.5)*100;document.getElementById('topProgress').style.width=pct+'%';}

/* ============ ROUTER ============ */
const chips=document.getElementById('chips');
chips.innerHTML=NAV.map(([id,l])=>`<a href="#${id}" data-v="${id}">${l}</a>`).join('');
const app=document.getElementById('app');
function nextLinks(id){const i=NAV.findIndex(n=>n[0]===id);const p=NAV[i-1],n=NAV[i+1];
  return `<div class="wrap next">${p?`<a href="#${p[0]}">← ${p[1]}</a>`:'<span></span>'}${n?`<a href="#${n[0]}">${n[1]} →</a>`:''}</div>`;}
function head(eb,h,p){return `<div class="wrap page-head"><p class="eyebrow">${eb}</p><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;}
function route(){
  let id=(location.hash||'#home').slice(1); if(!NAV.some(n=>n[0]===id)) id='home';
  chips.querySelectorAll('a').forEach(a=>a.classList.toggle('on',a.dataset.v===id));
  const on=chips.querySelector('.on'); if(on&&chips.offsetParent) on.scrollIntoView({inline:'center',block:'nearest'});
  let hit=false;document.querySelectorAll('#tabbar a').forEach(a=>{const m=a.dataset.v===id;a.classList.toggle('on',m);if(m)hit=true;});document.getElementById('moreBtn').classList.toggle('on',!hit);
  const sh=document.getElementById('sheet');if(!sh.hidden){sh.hidden=true;sh.innerHTML='';}
  app.innerHTML=`<div class="view">${VIEWS[id]()}${id==='home'?'':nextLinks(id)}</div>`;
  (INIT[id]||(()=>{}))();
  window.scrollTo(0,0);
}
window.addEventListener('hashchange',route);
document.getElementById('moreBtn').addEventListener('click',()=>{const cur=(location.hash||'#home').slice(1);
  openSheet(`<div class="sheet-head"><div><p class="eyebrow">Мәзір</p><h2>Барлық бөлімдер</h2></div><button class="close" aria-label="Жабу">✕</button></div><div class="menu-grid">${NAV.map(([id,l],i)=>`<a href="#${id}" class="${id===cur?'on':''}"><small>${String(i+1).padStart(2,'0')}</small>${l}</a>`).join('')}</div>`);
  document.querySelectorAll('.menu-grid a').forEach(a=>a.addEventListener('click',()=>{if(a.getAttribute('href')===(location.hash||'#home')){const s=document.getElementById('sheet');s.hidden=true;s.innerHTML='';}}));});

/* ============ VIEWS ============ */
const VIEWS={};const INIT={};

