function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
let curTask='test';

VIEWS.game=()=>`${head('Ойын','5 түрлі тапсырма','Әр тапсырманы орындаған соң негізгі нәтиже шығады. Барлық ұпай «Нәтиже» бетінде жиналады.')}
<section class="wrap section"><div class="task-tabs" id="tt">${TASKS.map((t,i)=>`<button class="task-tab" data-t="${t.id}"><small>${i+1}-тапсырма · ${t.k}</small><b>${t.n}</b><span class="st">${S.tasks[t.id]?`${S.tasks[t.id].s} / ${t.max}`:'орындалмаған'}</span></button>`).join('')}</div><div id="taskbox"></div></section>`;
INIT.game=()=>{document.getElementById('tt').addEventListener('click',e=>{const b=e.target.closest('.task-tab');if(!b)return;curTask=b.dataset.t;renderTask();});renderTask();};
function renderTabs(){document.querySelectorAll('.task-tab').forEach(b=>{b.classList.toggle('on',b.dataset.t===curTask);const t=TASKS.find(x=>x.id===b.dataset.t);b.querySelector('.st').textContent=S.tasks[t.id]?`${S.tasks[t.id].s} / ${t.max}`:'орындалмаған';});}
function finish(id,s,details){const t=TASKS.find(x=>x.id===id);S.tasks[id]={s,at:Date.now()};save();renderTabs();
  const pct=Math.round(s/t.max*100);
  const verdict=pct>=85?'Өте жақсы! Тақырыпты терең меңгердің.':pct>=60?'Жақсы нәтиже. Бірнеше деректі қайталап шық.':'Тақырыпты қайта оқып, тапсырманы қайталап көр.';
  const box=document.createElement('div');box.className='result';
  const idx=TASKS.findIndex(x=>x.id===id),nx=TASKS[idx+1];
  box.innerHTML=`<p class="eyebrow">Негізгі нәтиже</p><div class="score">${s} / ${t.max} · ${pct}%</div><h3>${verdict}</h3><p>${LESSON[id]}</p>${details&&details.length?`<ul>${details.map(d=>`<li>${d}</li>`).join('')}</ul>`:''}<div class="cta" style="margin-top:6px"><button class="btn" data-a="again">Қайта орындау</button>${nx?`<button class="btn solid" data-a="next">Келесі: ${nx.n}</button>`:`<a class="btn solid" href="#result">Қорытынды нәтиже</a>`}</div>`;
  box.querySelector('[data-a=again]').onclick=renderTask;
  if(nx) box.querySelector('[data-a=next]').onclick=()=>{curTask=nx.id;renderTask();document.getElementById('tt').scrollIntoView({behavior:'smooth'});};
  document.querySelector('#taskbox .task').appendChild(box);box.scrollIntoView({behavior:'smooth',block:'nearest'});
  if(Object.keys(S.tasks).length===5) toast('Барлық тапсырма орындалды!');
}
function renderTask(){renderTabs();const tb=document.getElementById('taskbox');const t=TASKS.find(x=>x.id===curTask);
 tb.innerHTML=`<div class="task"><div><p class="eyebrow">${t.k}</p><h2>${t.n}</h2></div><div id="tbody"></div></div>`;
 const body=document.getElementById('tbody');
 if(curTask==='test'){let s=0,d=0;const wrong=[];
  body.innerHTML=TEST.map((q,i)=>`<div class="q" data-i="${i}"><p>${i+1}. ${q.q}</p><div class="opts">${q.o.map((o,j)=>`<button class="opt" data-j="${j}">${o}</button>`).join('')}</div></div>`).join('');
  body.querySelectorAll('.q').forEach(qe=>qe.addEventListener('click',e=>{const b=e.target.closest('.opt');if(!b||b.disabled)return;const q=TEST[qe.dataset.i],j=+b.dataset.j;
   qe.querySelectorAll('.opt').forEach(x=>x.disabled=true);qe.querySelectorAll('.opt')[q.a].classList.add('ok');
   if(j===q.a)s++;else{b.classList.add('no');wrong.push(`${q.q} — ${q.o[q.a]}`);}
   if(++d===TEST.length)finish('test',s,wrong.map(w=>'Қайтала: '+w));}));
 }
 if(curTask==='order'){let items=shuffle(ORDER);
  const draw=()=>{body.innerHTML=`<p class="muted">Оқиғаларды ертеден кешке қарай ↑ ↓ батырмаларымен орналастыр.</p><ol class="order">${items.map((it,i)=>`<li><span>${it[0]}<span class="ans"></span></span><span class="mv"><button data-i="${i}" data-d="-1" aria-label="Жоғары">↑</button><button data-i="${i}" data-d="1" aria-label="Төмен">↓</button></span></li>`).join('')}</ol><div class="cta"><button class="btn solid" id="chk">Тексеру</button></div>`;
   body.querySelectorAll('.mv button').forEach(b=>b.onclick=()=>{const i=+b.dataset.i,j=i+ +b.dataset.d;if(j<0||j>=items.length)return;[items[i],items[j]]=[items[j],items[i]];draw();});
   document.getElementById('chk').onclick=()=>{const correct=ORDER.slice().sort((a,b)=>a[1]-b[1]);let s=0;const lis=body.querySelectorAll('.order li');
    items.forEach((it,i)=>{const ok=it[0]===correct[i][0];if(ok)s++;lis[i].classList.add(ok?'ok':'no');lis[i].querySelector('.ans').textContent=`${it[1]} жыл`+(ok?'':` · дұрыс орны: ${correct.findIndex(c=>c[0]===it[0])+1}`);});
    body.querySelectorAll('.mv button,#chk').forEach(x=>x.disabled=true);
    finish('order',s,[`Дұрыс реті: ${correct.map(c=>`${c[0]} (${c[1]})`).join(' → ')}`]);};};
  draw();
 }
 if(curTask==='match'){const right=shuffle(MATCH.map(m=>m[1]));const pairs={};let pick=null;
  const draw=()=>{body.innerHTML=`<p class="muted">Алдымен тұлғаны, сосын оның үлесін бас. Жұпты өзгерту үшін тұлғаны қайта бас.</p><div class="match"><div class="col">${MATCH.map((m,i)=>`<button class="mitem ${pick===i?'pick':''} ${pairs[i]!=null?'paired':''}" data-l="${i}">${m[0]}${pairs[i]!=null?`<span class="pair">→ ${right[pairs[i]]}</span>`:''}</button>`).join('')}</div><div class="col">${right.map((r,j)=>`<button class="mitem ${Object.values(pairs).includes(j)?'paired':''}" data-r="${j}" ${Object.values(pairs).includes(j)?'style="opacity:.45"':''}>${r}</button>`).join('')}</div></div><div class="cta"><button class="btn solid" id="chk" ${Object.keys(pairs).length<MATCH.length?'disabled':''}>Тексеру</button></div>`;
   body.querySelectorAll('[data-l]').forEach(b=>b.onclick=()=>{const i=+b.dataset.l;if(pairs[i]!=null)delete pairs[i];pick=i;draw();});
   body.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{if(pick==null)return;const j=+b.dataset.r;for(const k in pairs)if(pairs[k]===j)delete pairs[k];pairs[pick]=j;pick=null;draw();});
   const c=document.getElementById('chk');if(c)c.onclick=()=>{let s=0;const det=[];MATCH.forEach((m,i)=>{const ok=right[pairs[i]]===m[1];if(ok)s++;else det.push(`${m[0]} — ${m[1]}`);body.querySelector(`[data-l="${i}"]`).classList.add(ok?'ok':'no');});body.querySelectorAll('.mitem,#chk').forEach(x=>x.disabled=true);finish('match',s,det.map(d=>'Дұрысы: '+d));};};
  draw();
 }
 if(curTask==='map'){let k=0,s=0;const det=[];const qs=shuffle(MAPQ);
  body.innerHTML=`<div class="mapq"><p class="prompt" id="mp"></p><div class="map-box" id="mqbox">${mapSVG({labels:false,layers:false})}</div><p class="muted" id="mfb">Картадан облысты бас.</p></div>`;
  const box=document.getElementById('mqbox');const ask=()=>{document.getElementById('mp').innerHTML=`${k+1}/${qs.length}. <span>${qs[k][0]}</span>`;};ask();
  box.addEventListener('click',e=>{const p=e.target.closest('.obl');if(!p||k>=qs.length)return;const ans=qs[k][1];const ok=p.dataset.id===ans;
   box.querySelectorAll('.obl').forEach(x=>x.classList.remove('right','wrong'));box.querySelector(`[data-id="${ans}"]`).classList.add('right');if(!ok)p.classList.add('wrong');
   if(ok)s++;else det.push(`${qs[k][0]} — ${OBL[ans].n}`);
   document.getElementById('mfb').textContent=ok?`Дұрыс! ${OBL[ans].n}.`:`Қате. Дұрыс жауап: ${OBL[ans].n}.`;
   k++;if(k<qs.length)setTimeout(()=>{box.querySelectorAll('.obl').forEach(x=>x.classList.remove('right','wrong'));ask();},1100);else{document.getElementById('mp').textContent='Тапсырма аяқталды';finish('map',s,det.map(d=>'Қайтала: '+d));}});
 }
 if(curTask==='tf'){const ans={};
  body.innerHTML=`<div class="tf">${TF.map((t,i)=>`<div class="row" data-i="${i}"><span>${i+1}. ${t[0]}</span><span class="btns"><button data-v="1">Ақиқат</button><button data-v="0">Жалған</button></span><span class="why" hidden>${t[2]}</span></div>`).join('')}</div><div class="cta"><button class="btn solid" id="chk" disabled>Тексеру</button></div>`;
  body.querySelectorAll('.row').forEach(r=>r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;ans[r.dataset.i]=b.dataset.v==='1';r.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));document.getElementById('chk').disabled=Object.keys(ans).length<TF.length;}));
  document.getElementById('chk').onclick=()=>{let s=0;TF.forEach((t,i)=>{const r=body.querySelector(`[data-i="${i}"]`),ok=ans[i]===t[1];if(ok)s++;r.classList.add(ok?'ok':'no');r.querySelector('.why').hidden=false;});body.querySelectorAll('button').forEach(x=>x.disabled=true);finish('tf',s,[]);};
 }
}

function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
